/* Generated by scripts/build-fallback.php — edit resources/js/housekeeping-board.js instead. */
/*
|--------------------------------------------------------------------------
| The housekeeping pipeline
|--------------------------------------------------------------------------
| Dragging a room from one column to another.
|
| The rules are deliberately narrow, and they are the same three the server
| enforces:
|
|   Occupied → Dirty      the guest has gone, the room needs doing
|   Ready    → Dirty      it was used, or somebody had a look and disagreed
|   Cleaning → nowhere    a room being made up cannot be dragged at all
|
| Everything else — starting a clean, finishing one — is a button, because
| those are events with a time attached and a drag is a poor way to record a
| time. The buttons work with this script switched off, which is the point: a
| housekeeping terminal is exactly the machine whose browser is eight years old.
|
| The server checks all of this again. A rule that lives only here is a rule
| that a stale tab, a double-tap or a curl command does not have to obey.
*/

(function () {
    'use strict';

    const board = document.querySelector('[data-hk-board]');
    if (!board) return;

    const moveUrl = board.getAttribute('data-move');
    const token = (document.querySelector('meta[name="csrf-token"]') || {}).content || '';

    const $$ = (selector, scope) => Array.prototype.slice.call((scope || document).querySelectorAll(selector));

    let dragging = null;

    function targetsOf(tile) {
        return (tile.getAttribute('data-targets') || '').split(',').filter(Boolean);
    }

    /* ── Picking a tile up ───────────────────────────────────────────────── */

    $$('[data-hk-tile]', board).forEach(function (tile) {
        if (tile.getAttribute('draggable') !== 'true') return;

        tile.addEventListener('dragstart', function (event) {
            dragging = tile;
            tile.classList.add('is-dragging');

            // Firefox will not start a drag without something in the payload.
            try {
                event.dataTransfer.setData('text/plain', tile.getAttribute('data-room'));
                event.dataTransfer.effectAllowed = 'move';
            } catch (e) {}

            // Light up only the columns this tile is allowed to land in, so the
            // rule is visible before the drop rather than explained after it.
            targetsOf(tile).forEach(function (stage) {
                const column = board.querySelector('[data-hk-column="' + stage + '"]');
                if (column) column.classList.add('is-target');
            });
        });

        tile.addEventListener('dragend', function () {
            tile.classList.remove('is-dragging');
            dragging = null;

            $$('[data-hk-column]', board).forEach(function (column) {
                column.classList.remove('is-target', 'is-over');
            });
        });
    });

    /* ── Dropping it ─────────────────────────────────────────────────────── */

    $$('[data-hk-column]', board).forEach(function (column) {
        const stage = column.getAttribute('data-hk-column');

        column.addEventListener('dragover', function (event) {
            if (!dragging) return;
            if (targetsOf(dragging).indexOf(stage) === -1) return;

            // preventDefault is what makes an element a drop target at all.
            event.preventDefault();
            event.dataTransfer.dropEffect = 'move';
            column.classList.add('is-over');
        });

        column.addEventListener('dragleave', function () {
            column.classList.remove('is-over');
        });

        column.addEventListener('drop', function (event) {
            if (!dragging) return;
            if (targetsOf(dragging).indexOf(stage) === -1) return;

            event.preventDefault();
            column.classList.remove('is-over');

            move(dragging, stage);
        });
    });

    /* ── Telling the server ──────────────────────────────────────────────── */

    function move(tile, stage) {
        const body = new FormData();

        body.append('room_id', tile.getAttribute('data-room'));
        body.append('to', stage);
        // Sent so the server can check the same drag rule rather than trusting
        // that the browser did.
        body.append('from', tile.getAttribute('data-stage'));

        tile.classList.add('is-busy');

        fetch(moveUrl, {
            method: 'POST',
            headers: {
                Accept: 'application/json',
                'X-CSRF-TOKEN': token,
                'X-Requested-With': 'XMLHttpRequest',
            },
            credentials: 'same-origin',
            body: body,
        })
            .then(function (response) {
                return response.json().then(function (data) {
                    return { ok: response.ok, data: data };
                });
            })
            .then(function (result) {
                if (!result.ok) {
                    say(result.data.message || 'That move was refused.', true);
                    tile.classList.remove('is-busy');

                    return;
                }

                /*
                 * The page is reloaded rather than the tile moved by hand.
                 * Column counts, the "arriving today" flags and the log at the
                 * bottom all change with a move, and a board that is half
                 * up to date is worse than one that took a second to refresh.
                 */
                window.location.reload();
            })
            .catch(function () {
                say('Could not reach the server. Nothing was changed.', true);
                tile.classList.remove('is-busy');
            });
    }

    /* ── Saying something went wrong ─────────────────────────────────────── */

    function say(message, isError) {
        let box = document.querySelector('[data-hk-toast]');

        if (!box) {
            box = document.createElement('div');
            box.setAttribute('data-hk-toast', '');
            box.className = 'nv-hkb-toast';
            document.body.appendChild(box);
        }

        box.textContent = message;
        box.classList.toggle('is-error', !!isError);
        box.classList.add('is-on');

        window.clearTimeout(box.timer);
        box.timer = window.setTimeout(function () { box.classList.remove('is-on'); }, 5000);
    }
})();
